package android.util; public class SparseBooleanArray { final SparseArray<Boolean> a=new SparseArray<>(); public SparseBooleanArray(){} public SparseBooleanArray(int n){} public boolean get(int k){return get(k,false);} public boolean get(int k,boolean d){return a.get(k,d);} public void put(int k,boolean v){a.put(k,v);} public void append(int k,boolean v){a.put(k,v);} public void clear(){a.clear();} public int size(){return a.size();} public int keyAt(int i){return a.keyAt(i);} public boolean valueAt(int i){return a.valueAt(i);} public int indexOfKey(int k){return a.indexOfKey(k);} public void delete(int k){a.delete(k);} }
